def atualizar_status_antigos(apps, schema_editor):
    Instituicao = apps.get_model('ongs', 'Instituicao')
    banco = Instituicao.objects.using(schema_editor.connection.alias)
    banco.filter(status='ativo').update(status='ativa')
    banco.filter(status='inativo').update(status='inativa')


